#include <stdint.h>
#include <time.h>

int64_t orca_idle_clock_ms(void) {
    struct timespec ts;
#ifdef __APPLE__
    const clockid_t clock_id = CLOCK_UPTIME_RAW;
#else
    const clockid_t clock_id = CLOCK_MONOTONIC;
#endif
    if (clock_gettime(clock_id, &ts) != 0) return -1;
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

